    }
  }
}

function normalizeProfile(profile) {
  const out = {};
  if ('name' in profile) out.name = profile.name;
  if ('labels' in profile) out.labels = { ...profile.labels };
  return out;
}

export async function callTool(name, arguments_) {
  const tool = TOOLS.find((t) => t.name === name);
  if (!tool) {
    fail(`Unknown tool: ${name}`);
  }
  const args = arguments_ || {};
  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
    fail('Expected arguments object');
  }
  const knownArgs = new Set(Object.keys(tool.inputSchema.properties || {}));
  for (const key of Object.keys(args)) {
    if (!knownArgs.has(key)) {
      fail(`Unknown argument "${key}"`);
    }
  }
  const required = tool.inputSchema.required || [];
  for (const key of required) {
    if (!(key in args)) {
      fail(`Missing required argument "${key}"`);
    }
  }
  if ('profile' in args) {
    validateProfile(args.profile, 'profile');
  }
  const normalized = normalizeProfile(args.profile);
  return {
    content: [{ type: 'text', text: JSON.stringify(normalized) }],
  };
}
